import { Close as CloseIcon } from '@mui/icons-material';
import { Button, Dialog, DialogActions, DialogContent, DialogTitle, IconButton } from '@mui/material';
import { SimulatorViewData } from '../data/Common/SimulatorViewData';
import { ConfigurationData } from '../data/ConfigurationData';
import { Job } from '../data/Job';
import { MachineData } from '../data/Machine/MachineData';
import { MachineStateData } from '../data/MachineStateData';
import { FullSizeCNCViewer } from './MachineViewer/FullSizeCNCViewer';

interface SimulatorDialogProps {
    open: boolean;
    onClose: () => void;
    simulatorViewData: SimulatorViewData;
    maxWidth?: 'sm' | 'md' | 'lg' | 'xl';
}

export function SimulatorDialog({ open, onClose, simulatorViewData, maxWidth = 'xl' }: SimulatorDialogProps) {
    const config = ConfigurationData.Instance;
    const machineState = MachineStateData.Instance;
    const machineData = MachineData.Instance;
    const job = machineState.currentJob || new Job();

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth={maxWidth}
            fullWidth
            PaperProps={{ sx: { height: '90vh' } }}
        >
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: config.primaryColor,
                color: 'white',
                py: 2,
                px: 3
            }}>
                Job Simulator
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: 'white',
                        '&:hover': {
                            backgroundColor: 'rgba(255, 255, 255, 0.1)'
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent sx={{ p: 0, height: '100%' }}>
                <FullSizeCNCViewer
                    simulatorViewData={simulatorViewData}
                    machineState={machineState}
                    machineData={machineData}
                    job={job}
                    enableSpindleDrag={true}
                    showSettingsButton={true}
                />
            </DialogContent>
            <DialogActions sx={{ p: 2, justifyContent: 'flex-end', borderTop: `1px solid ${config.borderColor}` }}>
                <Button
                    onClick={onClose}
                    variant="contained"
                    sx={{
                        backgroundColor: config.primaryColor,
                        '&:hover': {
                            backgroundColor: config.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    Close
                </Button>
            </DialogActions>
        </Dialog>
    );
}
